def public_context(request):
    return {"public_guides": GUIDES}


@require_GET
def guide(request, slug):
    item = next((item for item in GUIDES if item[0] == slug), None)
    if item is None:
        raise Http404
    return render(request, "cashflow/guide.html", {"guide": item})
